module.exports = /*#__PURE__*/JSON.parse('{"verdicts":[{"slug":"false","colorCode":"#DC2626","iconName":"x-circle","locales":{"en":{"name":"False","description":"The claim is completely factually inaccurate, fabricated, or contradicts proven scientific evidence."},"sw":{"name":"Uongo","description":"Madai haya si ya kweli kabisa, yamebuniwa, au yanapingana na ushahidi wa kisayansi uliothibitishwa."}}},{"slug":"true","colorCode":"#16A34A","iconName":"check-circle","locales":{"en":{"name":"True","description":"The claim is accurate, verified with official primary sources and certified health records."},"sw":{"name":"Kweli","description":"Madai haya ni sahihi, yamethibitishwa na vyanzo rasmi vya kimsingi na rekodi za afya."}}},{"slug":"misleading","colorCode":"#D97706","iconName":"alert-triangle","locales":{"en":{"name":"Misleading","description":"Contains elements of truth but is taken out of context, exaggerated, or manipulated to misinform."},"sw":{"name":"Upotoshaji","description":"Ina ukweli kiasi lakini imetolewa nje ya muktadha, imekuzwa, au imetumiwa kupotosha umma."}}},{"slug":"unproven","colorCode":"#6B7280","iconName":"help-circle","locales":{"en":{"name":"Unproven","description":"There is insufficient verified scientific or clinical data to validate the claim at this time."},"sw":{"name":"Haijathibitishwa","description":"Hakuna data za kutosha za kisayansi au za kitabibu kuthibitisha madai haya kwa wakati huu."}}}],"categories":[{"slug":"mpoxfacts","locales":{"en":{"name":"MpoxFacts","description":"Dedicated fact-checking desk for monkeypox (Mpox) transmission, vaccines, and treatment myths."},"sw":{"name":"Ukweli Kuhusu Mpox","description":"Dawati maalum la ukaguzi wa habari kuhusu maambukizi, chanjo na uzushi wa matibabu ya Mpox."}}},{"slug":"epidemics-health","locales":{"en":{"name":"Epidemics & Public Health","description":"Verifying health rumors across DRC and the Great Lakes region."},"sw":{"name":"Magonjwa ya Mlipuko na Afya ya Umma","description":"Kuhakiki uzushi wa kiafya katika Jamhuri ya Kidemokrasia ya Kongo na kanda ya Maziwa Makuu."}}},{"slug":"vaccines-science","locales":{"en":{"name":"Vaccines & Science","description":"Debunking clinical conspiracy theories and laboratory science falsifications."},"sw":{"name":"Chanjo na Sayansi","description":"Kupinga nadharia potofu za njama za chanjo na upotoshaji wa kisayansi."}}}],"authors":[{"id":"fiston-mahamba","name":"Fiston Mahamba","role":"Senior Editor & Investigative Journalist","bio":"Co-founder of Congo Check, specializing in health fact-checking, armed conflict misinformation, and digital verification in Central Africa.","organization":"Congo Check","twitterHandle":"@fistonmahamba"},{"id":"ruth-kutemba","name":"Ruth Kutemba","role":"Health Fact-Checker","bio":"Fact-checking reporter covering epidemic alerts, hospital confirmations, and social media hoaxes in Goma and Kinshasa.","organization":"Congo Check","twitterHandle":"@ruthkutemba"},{"id":"john-mukengere","name":"John Mukengere","role":"Regional Fact-Checker","bio":"Fact-checking correspondent in Eastern DRC monitoring WhatsApp audio broadcasts and Swahili-language radio rumors.","organization":"Congo Check","twitterHandle":"@jmukengere"}],"factChecks":[{"slug":"bill-gates-predicted-mpox-simulation-nti","claimDate":"2024-10-18","publishDate":"2024-10-22","verdictSlug":"false","categorySlug":"mpoxfacts","authorId":"fiston-mahamba","editorId":"ruth-kutemba","verificationMethod":"PROTOCOL_3PFCP","isFeatured":true,"image":"https://images.unsplash.com/photo-1584483766114-2cea6facdf57?w=1200&auto=format&fit=crop&q=80","sources":[{"title":"NTI Official Statement on May 2022 Simulation Exercise","url":"https://www.nti.org/analysis/articles/preventing-global-catastrophic-biological-risks/"},{"title":"World Health Organization (WHO) Mpox Surveillance Bulletin","url":"https://www.who.int/emergencies/disease-outbreak-news"},{"title":"Institut Pasteur: History and Isolation of Monkeypox","url":"https://www.pasteur.fr/en"}],"locales":{"en":{"title":"Did Bill Gates Predict the Spread of Mpox? No, It Was an NTI Preparedness Simulation Exercise","claim":"American billionaire Bill Gates predicted and planned the current Mpox outbreak in advance during 2022 to profit from vaccines.","claimant":"Viral Facebook posts and TikTok video conspiracy claims","verdictSummary":"FALSE. The circulating video is an excerpt from a tabletop pandemic crisis simulation organized by the Nuclear Threat Initiative (NTI) in March 2021 to test global bio-security response systems. Bill Gates did not orchestrate or predict the real outbreak.","imageCaption":"Viral claim falsely alleging a pre-planned biological outbreak orchestrated by Bill Gates.","explanation":"### Context of the Claim\\nIn recent weeks, viral posts on Facebook and TikTok in Central and East Africa claimed that American philanthropist Bill Gates had foreseen and planned the spread of Mpox (monkeypox). The posts claimed: \\"Bill Gates pox has arrived. He predicted it and now it is here... listen carefully.\\"\\n\\n### Congo Check Verification Process\\nOur editorial desk investigated the origin of this video and claim:\\n\\n1. **Origin of the Footage:** Reverse video analysis reveals the clip originates from a tabletop pandemic preparedness exercise hosted by the NGO **Nuclear Threat Initiative (NTI)** in March 2021 in Munich.\\n2. **The Simulation Scenario:** The exercise gathered former heads of state, public health leaders, and scientists to simulate an imaginary biological pathogen scenario set arbitrarily in May 2022. Organizers chose monkeypox simply as a recognized representative pathogen with known transmission profiles, not as a prophecy.\\n3. **Official Response from WHO:** Eugene Kabambi, communications officer at the World Health Organization (WHO) in Kinshasa, confirmed to Congo Check that these allegations are completely baseless conspiracy theories intended to instill distrust in legitimate medical counter-measures and vaccines.\\n4. **NTI Clarification:** In a formal statement, the Nuclear Threat Initiative reiterated: \\"The fact that monkeypox is currently spreading in multiple countries is a sheer coincidence. The risks posed by poxviruses have been studied and documented by virologists since 1958.\\"\\n\\n### Scientific Evidence\\nMonkeypox was first identified in laboratory monkeys in 1958 in Copenhagen, Denmark, and the first documented human infection occurred in 1970 in the Democratic Republic of the Congo. It is a zoonotic orthopoxvirus that has existed in wild mammalian reservoirs for centuries.\\n\\n### Verdict\\nThe claim that Bill Gates predicted or planned the Mpox outbreak is **FALSE**. The video depicts a hypothetical preparedness simulation conducted by an independent non-profit organisation."},"sw":{"title":"Je, Bill Gates Alitabiri Kuenea kwa Mpox? Hapana, Lilikuwa Zoezi la Kujiandaa la Shirika la NTI","claim":"Bilionea wa Marekani Bill Gates alitabiri na kupanga mapema kuenea kwa Mpox mnamo 2022 ili kupata faida ya kuuza chanjo.","claimant":"Machapisho ya virusi kwenye Facebook na video za uzushi kwenye TikTok","verdictSummary":"UONGO. Video inayosambazwa ni kipande kutoka kwa zoezi la uigaji wa kukabiliana na majanga ya kiafya lililoandaliwa na shirika la Nuclear Threat Initiative (NTI) mnamo Machi 2021. Bill Gates hakupanga wala kutabiri mlipuko halisi wa ugonjwa huo.","imageCaption":"Ujumbe wa uzushi unaodai kimakosa kuwa kuenea kwa Mpox kulipangwa kimakusudi.","explanation":"### Muktadha wa Madai Haya\\nKatika wiki za hivi karibuni, machapisho yaliyosambaa kwa kasi kwenye mitandao ya kijamii kama Facebook na TikTok nchini DRC na nchi za Afrika Mashariki yalieleza kuwa bilionea Bill Gates alikuwa ametabiri mlipuko wa Mpox. Ujumbe huo ulisema: \\"Ugonjwa wa ndui wa Bill Gates umewasili. Alitabiri na sasa upo hapa... sikilizeni kwa makini.\\"\\n\\n### Ukaguzi na Uchunguzi wa Congo Check\\nDawati letu la ukaguzi lilifanya uchunguzi wa kina kupitia itifaki yetu ya 3PFCP:\\n\\n1. **Asili ya Video:** Utafutaji wa picha na video unathibitisha kuwa picha hizo zilitoka kwenye zoezi la uigaji wa janga lililofanyika Munich mwezi Machi 2021 na shirika la **Nuclear Threat Initiative (NTI)**.\\n2. **Uhalisia wa Zoezi Hilo:** Zoezi hilo lilikutanisha wataalamu wa afya na viongozi ili kujadili namna dunia inavyoweza kujiandaa iwapo janga jipya litatokea. Walichagua ugonjwa wa ndui ya nyani kama mfano wa kinadharia tu.\\n3. **Kauli ya Shirika la Afya Duniani (WHO):** Eugene Kabambi, afisa wa mawasiliano wa WHO jijini Kinshasa, alithibitishia Congo Check kuwa habari hizi ni uzushi mtupu unaolenga kuwatisha wananchi wasipokee chanjo na matibabu sahihi.\\n4. **Ufafanuzi wa NTI:** Shirika la NTI lilitoa tamko rasmi: \\"Ukweli kwamba Mpox inasambaa katika nchi kadhaa ni tukio la kawaida la asili na si matokeo ya zoezi la uigaji. Virusi hivi vimekuwepo tangu mwaka 1958.\\"\\n\\n### Ushahidi wa Kisayansi\\nVirusi vya Mpox viligunduliwa kwa mara ya kwanza kwa nyani wa maabara huko Copenhagen mnamo 1958, na kisa cha kwanza cha binadamu kilirekodiwa katika Jamhuri ya Kidemokrasia ya Kongo mnamo 1970. Ni ugonjwa unaotokana na wanyama pori na umekuwepo kwa miongo mingi.\\n\\n### Uamuzi (Verdict)\\nMadai kwamba Bill Gates alitabiri au kupanga kuenea kwa Mpox ni **UONGO**. Video inayoonyeshwa ni ya zoezi la kujiandaa la kisayansi na si mpango wa siri."}}},{"slug":"cassava-leaves-sugarcane-juice-cure-mpox","claimDate":"2024-09-20","publishDate":"2024-09-24","verdictSlug":"false","categorySlug":"mpoxfacts","authorId":"john-mukengere","editorId":"fiston-mahamba","verificationMethod":"EXPERT_INTERVIEW","isFeatured":true,"image":"https://images.unsplash.com/photo-1576086213369-97a306d36557?w=1200&auto=format&fit=crop&q=80","sources":[{"title":"Ministry of Public Health DRC - National Mpox Response Protocol","url":"https://sante.gouv.cd"},{"title":"Africa CDC Clinical Management Guidelines for Mpox","url":"https://africacdc.org"}],"locales":{"en":{"title":"Cassava Leaves and Sugarcane Juice Mixture Does Not Cure or Prevent Mpox","claim":"Drinking a boiled concoction of crushed cassava leaves combined with pure sugarcane juice completely cures Mpox within 48 hours.","claimant":"Widely shared WhatsApp voice notes circulating in Goma, Bukavu, and Uvira","verdictSummary":"FALSE. There is zero clinical or pharmacological evidence that cassava leaves and sugarcane juice can eliminate the Mpox virus. Medical authorities warn that relying on unproven remedies delays essential medical care and risks severe complications.","imageCaption":"Herbal remedy rumor falsely advertised as an anti-viral cure for Mpox.","explanation":"### The Rumor\\nA viral audio message in Swahili and French circulated extensively in North Kivu and South Kivu advising citizens to avoid clinics and instead boil cassava leaves (sombe) with sugarcane juice to treat monkeypox lesions.\\n\\n### Scientific Verification\\nCongo Check interviewed Dr. Stephane Hans Bateyi, medical coordinator of the Expanded Program on Immunization (EPI) in North Kivu:\\n\\n- **No Antiviral Action:** Neither cassava leaves nor sugarcane possess antiviral properties against Orthopoxviruses.\\n- **Risk of Toxicity:** Unprocessed or improperly prepared cassava leaves contain cyanogenic glucosides which can cause cyanide poisoning when ingested in concentrated quantities.\\n- **Delayed Care Warning:** Delaying hospital admission when suffering from Mpox can lead to secondary bacterial skin infections, sepsis, corneal scarring, and death.\\n\\n### Official Treatment\\nMpox must be managed in healthcare facilities using supportive care (pain management, nutritional support, antiseptic skin care) and antiviral therapeutics where indicated by licensed physicians.\\n\\n### Verdict\\nThis claim is **FALSE** and dangerous for public health."},"sw":{"title":"Mchanganyiko wa Majani ya Muhogo na Maji ya Miwa Si Dawa ya Kutibu Mpox","claim":"Kunywa mchanganyiko uliochemshwa wa majani ya muhogo (sombe) na maji ya miwa kunaponya ugonjwa wa Mpox ndani ya saa 48.","claimant":"Sauti ya WhatsApp iliyosambazwa kwa wingi huko Goma, Bukavu na Uvira","verdictSummary":"UONGO. Hakuna ushahidi wowote wa kitabibu au wa kisayansi unaothibitisha kuwa majani ya muhogo na miwa yanaua virusi vya Mpox. Madaktari wanaonya kuwa kufuata uzushi huu kunachelewesha matibabu hospitalini na kuhatarisha maisha.","imageCaption":"Dawa ya kienyeji inayodaiwa kimakosa kuwa tiba ya ugonjwa wa Mpox.","explanation":"### Uzushi Huu Ulivyoanza\\nUjumbe wa sauti kwenye WhatsApp ulisambaa sana katika maeneo ya Kivu Kaskazini na Kivu Kusini ukiwashauri wananchi wasiende hospitali bali wachemshe majani ya muhogo na maji ya miwa ili kuponya upele na vidonda vya Mpox.\\n\\n### Ukaguzi wa Kisayansi\\nCongo Check ilizungumza na Dkt. Stephane Hans Bateyi, mratibu wa afya katika eneo la Kivu Kaskazini:\\n\\n- **Hakuna Uwezo wa Kuua Virusi:** Majani ya muhogo wala maji ya miwa hayana kinga wala uwezo wa kuua virusi vya Orthopoxvirus.\\n- **Hatari ya Sumu:** Majani ya muhogo yasiyopikwa vizuri yana kemikali za cyanide ambazo zinaweza kusababisha sumu mwilini iwapo yatanywewa kwa wingi.\\n- **Ucheleweshaji wa Matibabu:** Mgonjwa anapochelewa kwenda kituo cha afya, vidonda vya Mpox vinaweza kupata maambukizi ya bakteria, uharibifu wa macho, au hata kusababisha kifo.\\n\\n### Matibabu Sahihi\\nWagonjwa wa Mpox wanapaswa kupelekwa mara moja katika vituo vya afya vilivyoidhinishwa ili kupata matunzo maalum, dawa za kutuliza maumivu na lishe sahihi.\\n\\n### Uamuzi (Verdict)\\nMadai haya ni **UONGO** na ni hatari kwa afya ya jamii."}}},{"slug":"confirmed-mpox-case-sendwe-hospital-lubumbashi","claimDate":"2024-09-15","publishDate":"2024-09-18","verdictSlug":"true","categorySlug":"mpoxfacts","authorId":"ruth-kutemba","editorId":"fiston-mahamba","verificationMethod":"OFFICIAL_HEALTH_BULLETIN","isFeatured":false,"image":"https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1200&auto=format&fit=crop&q=80","sources":[{"title":"Provincial Health Division (DPS) of Haut-Katanga Press Briefing","url":"https://dps-hautkatanga.cd"},{"title":"Sendwe General Reference Hospital Medical Directorate","url":"https://lubumbashi-health.org"}],"locales":{"en":{"title":"True: Confirmed Mpox Patient Successfully Treated at Sendwe Hospital in Lubumbashi","claim":"A woman suffering from laboratory-confirmed Mpox was admitted for specialized isolation and clinical care at Jason Sendwe Hospital in Lubumbashi.","claimant":"Local community health monitors and medical reports in Haut-Katanga","verdictSummary":"TRUE. Provincial health authorities in Haut-Katanga confirmed that a female patient exhibiting classic Mpox symptoms tested positive via PCR analysis and was safely isolated and treated under strict infection prevention protocols.","imageCaption":"Jason Sendwe Reference Hospital in Lubumbashi, Haut-Katanga.","explanation":"### Verification\\nIn mid-September 2024, reports surfaced stating that an Mpox patient had arrived at the Jason Sendwe General Reference Hospital in Lubumbashi.\\n\\nCongo Check contacted Dr. Jean-Luc Kakudji, provincial minister of health for Haut-Katanga, and the hospital medical directorate:\\n\\n- The patient, a 28-year-old resident, presented with fever, lymphadenopathy, and vesicular lesions.\\n- Swabs sent to the National Institute of Biomedical Research (INRB) yielded positive PCR confirmation for Clade Ib Mpox.\\n- Contact tracing was enacted immediately and the patient responded favorably to hospital-based supportive care.\\n\\n### Verdict\\nThis report is **TRUE** and reflects verified epidemiological reporting."},"sw":{"title":"Kweli: Mgonjwa wa Mpox Alipokelewa na Kutibiwa Katika Hospitali ya Sendwe Huko Lubumbashi","claim":"Mwanamke mmoja aliyethibitishwa kuwa na maambukizi ya Mpox alilazwa kwa uangalizi maalum katika Hospitali ya Jason Sendwe jijini Lubumbashi.","claimant":"Taarifa za wahudumu wa afya na duru za kijamii jimboni Haut-Katanga","verdictSummary":"KWELI. Mamlaka za afya za mkoa wa Haut-Katanga zilithibitisha kuwa mgonjwa aliyekuwa na dalili za Mpox alipimwa na kukutwa na virusi kupitia kipimo cha maabara (PCR), na akawekwa katika wadi maalum ya wagonjwa wa kuambukiza.","imageCaption":"Hospitali ya Rufaa ya Jason Sendwe huko Lubumbashi, Haut-Katanga.","explanation":"### Uthibitisho wa Taarifa Hii\\nKatikati ya Septemba 2024, taarifa zilisambaa kuwa mgonjwa wa Mpox amewasili katika Hospitali ya Rufaa ya Jason Sendwe huko Lubumbashi.\\n\\nCongo Check iliwasiliana na idara ya afya ya jimbo la Haut-Katanga na uongozi wa hospitali:\\n\\n- Mgonjwa huyo mwenye umri wa miaka 28 alikuwa na homa kali, kuvimba tezi na vipele mwilini.\\n- Vipimo vilivyotumwa katika maabara kuu ya INRB vilithibitisha maambukizi ya virusi vya Mpox aina ya Clade Ib.\\n- Mgonjwa alitengwa na kupatiwa matunzo hadi hali yake ilipopata nafuu.\\n\\n### Uamuzi (Verdict)\\nTaarifa hii ni **KWELI** na imethibitishwa na vyanzo rasmi vya afya."}}},{"slug":"mpox-vaccine-depopulation-plot-rwanda","claimDate":"2024-09-28","publishDate":"2024-09-30","verdictSlug":"false","categorySlug":"vaccines-science","authorId":"fiston-mahamba","editorId":"john-mukengere","verificationMethod":"OFFICIAL_HEALTH_BULLETIN","isFeatured":false,"image":"https://images.unsplash.com/photo-1632833239869-a37e3a5806d2?w=1200&auto=format&fit=crop&q=80","sources":[{"title":"European Commission Directorate-General for Health and Food Safety","url":"https://health.ec.europa.eu"},{"title":"Africa CDC Mpox Vaccine Delivery Oversight Committee","url":"https://africacdc.org"}],"locales":{"en":{"title":"No, Mpox Vaccines Are Not a Western Plot to Depopulate Congo for Rwanda","claim":"Mpox vaccines donated to the DRC are contaminated bioweapons created by the West to eliminate the Congolese population for the benefit of Rwanda.","claimant":"Political influence accounts and sensationalist video blogs on Facebook and X","verdictSummary":"FALSE. The MVA-BN vaccines received by the DRC were manufactured by Bavarian Nordic in Denmark and donated through the European Union and international public health partnerships. These identical vaccines have been administered safely across Europe and North America.","imageCaption":"European Union donation of MVA-BN vaccines at N’djili International Airport in Kinshasa.","explanation":"### The Conspiracy\\nFollowing the arrival of the first batch of 265,000 vaccine doses at Kinshasa airport in September 2024, political bloggers claimed the vaccines were designed to sterilize or exterminate Congolese citizens amid geopolitical tensions.\\n\\n### Our Verification\\nCongo Check verified the batch numbers, regulatory dossiers, and clinical safety approvals:\\n\\n1. **Proven Safety Record:** The vaccine delivered is **MVA-BN (Modified Vaccinia Ankara - Bavarian Nordic)**, licensed as JYNNEOS in the United States and IMVANEX in Europe. Millions of doses have been administered safely worldwide since 2013.\\n2. **Identical Formulations:** The vials shipped to DRC are identical in formulation to those used across European hospitals and public health agencies.\\n3. **Independent Local Quality Control:** Samples were inspected and cleared by the DRC National Pharmacovigilance Committee and the Ministry of Health before deployment.\\n\\n### Verdict\\nThe claim is **FALSE** and exploits sensitive geopolitical conflict to undermine public trust in lifesaving medical interventions."},"sw":{"title":"Hapana, Chanjo ya Mpox Si Mpango wa Kuangamiza Wakongo kwa Faida ya Rwanda","claim":"Chanjo za Mpox zilizotolewa msaada kwa DRC ni silaha za kibiolojia zilizotengenezwa na nchi za Magharibi kuangamiza idadi ya watu wa Kongo kwa faida ya Rwanda.","claimant":"Akaunti za uchochezi wa kisiasa na kurasa za video kwenye Facebook na mtandao wa X","verdictSummary":"UONGO. Chanjo za MVA-BN zilizopokewa na DRC zilitengenezwa na kampuni ya Bavarian Nordic nchini Denmark na kutolewa kupitia Umoja wa Ulaya na mashirika ya afya ya kimataifa. Chanjo hizi zinafanana kabisa na zile zilizotumika kwa usalama barani Ulaya na Amerika.","imageCaption":"Msaada wa chanjo za MVA-BN kutoka Umoja wa Ulaya katika uwanja wa ndege wa N’djili jijini Kinshasa.","explanation":"### Uzushi Huu wa Kisiasa\\nBaada ya kuwasili kwa shehena ya kwanza ya dozi 265,000 za chanjo jijini Kinshasa mwezi Septemba 2024, baadhi ya watu walisambaza madai ya uongo wakidai kuwa chanjo hizo zina sumu ya kuangamiza watu wa DRC.\\n\\n### Ukaguzi wa Congo Check\\nTimu yetu ilikagua nyaraka za kiufundi na usalama wa chanjo:\\n\\n1. **Usalama wa Kimataifa:** Chanjo iliyoletwa ni **MVA-BN**, inayojulikana kama JYNNEOS Marekani na IMVANEX Ulaya. Imetumika kwa miaka mingi na mamilioni ya watu duniani kote bila madhara ya sumu.\\n2. **Uthibitisho wa Maabara:** Mamlaka ya Dawa ya DRC na Kamati ya Kitaifa ya Uangalizi wa Dawa zilikagua shehena hiyo na kuthibitisha ubora na usalama wake.\\n3. **Ukweli Kuhusu Msaada:** Chanjo zilitolewa kama mshikamano wa dharura wa kukabili mlipuko unaoendelea katika bara la Afrika.\\n\\n### Uamuzi (Verdict)\\nMadai haya ni **UONGO** na yanalenga kutumia siasa za kikanda kupinga jitihada za kuokoa maisha ya wagonjwa."}}},{"slug":"pork-meat-consumption-mpox-transmission","claimDate":"2024-09-22","publishDate":"2024-09-24","verdictSlug":"false","categorySlug":"mpoxfacts","authorId":"john-mukengere","editorId":"ruth-kutemba","verificationMethod":"EXPERT_INTERVIEW","isFeatured":false,"image":"https://images.unsplash.com/photo-1544025162-d76694265947?w=1200&auto=format&fit=crop&q=80","sources":[{"title":"Food and Agriculture Organization (FAO) Veterinary Health Guidance","url":"https://www.fao.org"},{"title":"World Organisation for Animal Health (WOAH)","url":"https://www.woah.org"}],"locales":{"en":{"title":"False: Eating Thoroughly Cooked Pork Does Not Cause Mpox Contamination","claim":"Eating pork meat directly infects humans with monkeypox and causes skin boils across the face.","claimant":"Market rumors and social media panic in Lubumbashi butchers and food markets","verdictSummary":"FALSE. Domestic swine are not reservoir hosts for Mpox. Mpox is transmitted between humans through close physical contact, or from wild rodents and primates via hunting and handling bushmeat. Standard cooked livestock meat poses no risk of Mpox.","imageCaption":"Butchers and food markets in DRC affected by rumors regarding pork meat safety.","explanation":"### The Claim\\nRumors circulating in markets across Katanga claimed that pork meat was banned by sanitary inspectors because pigs carry Mpox.\\n\\n### What the Science Shows\\nVeterinary epidemiologists confirmed to Congo Check that:\\n\\n- Mpox reservoir hosts in the wild are primarily rodents (such as rope squirrels, tree squirrels, and Gambian pouched rats) and non-human primates.\\n- Domestic pigs do not transmit Mpox to humans.\\n- Cooking meat thoroughly destroys any bacterial pathogens or foodborne micro-organisms.\\n\\n### Verdict\\nThe claim that eating pork transmits Mpox is **FALSE**."},"sw":{"title":"Uongo: Kula Nyama ya Nguruwe Hakusababishi Maambukizi ya Mpox","claim":"Kula nyama ya nguruwe kunasababisha maambukizi ya moja kwa moja ya ugonjwa wa Mpox na vipele usoni.","claimant":"Uzushi katika masoko na maduka ya nyama jijini Lubumbashi na Kolwezi","verdictSummary":"UONGO. Nguruwe wa kufugwa si wanyama wanaobeba virusi vya Mpox. Ugonjwa huu huambukizwa baina ya binadamu kwa kugusana kimwili au kutoka kwa wanyama pori (panya na nyani wa msituni). Nyama ya mifugo iliyopikwa vizuri haina hatari ya Mpox.","imageCaption":"Masoko na maduka ya nyama yaliyoathiriwa na uzushi kuhusu nyama ya nguruwe.","explanation":"### Chanzo cha Uzushi\\nMadai yaliyoenea katika masoko ya Katanga yalisema kuwa serikali imepiga marufuku nyama ya nguruwe kwa sababu wanyama hao wanabeba virusi vya Mpox.\\n\\n### Ukweli wa Kisayansi\\nWataalamu wa mifugo na afya ya umma wamethibitishia Congo Check:\\n\\n- Wanyama wanaoeneza Mpox porini ni panya maalum wa msituni na nyani, wala si nguruwe wa nyumbani.\\n- Nyama yoyote ya mfugo inapopikwa kwa joto la kutosha huua vijidudu vyote vya magonjwa.\\n- Njia kuu ya maambukizi kwa sasa ni mgusano wa karibu kati ya binadamu na binadamu kupitia ngozi, nguo au matone ya majimaji.\\n\\n### Uamuzi (Verdict)\\nMadai kuwa kula nguruwe kunaeneza Mpox ni **UONGO**."}}},{"slug":"karisimbi-health-zone-1000-cases-exaggerated","claimDate":"2024-09-25","publishDate":"2024-09-29","verdictSlug":"misleading","categorySlug":"mpoxfacts","authorId":"john-mukengere","editorId":"fiston-mahamba","verificationMethod":"OFFICIAL_HEALTH_BULLETIN","isFeatured":false,"image":"https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=1200&auto=format&fit=crop&q=80","sources":[{"title":"North Kivu Provincial Health Division Weekly Epidemiological Report","url":"https://dpsnordkivu.cd"}],"locales":{"en":{"title":"Misleading: Karisimbi Health Zone Had Not Reached 1,000 Confirmed Mpox Cases","claim":"The Karisimbi health zone in Goma has officially surpassed 1,000 confirmed Mpox cases and hospitals are collapsing.","claimant":"Local sensationalist WhatsApp messages and radio soundbites","verdictSummary":"MISLEADING. While Karisimbi is one of the active transmission hotspots in North Kivu, official surveillance recorded 312 cumulative suspected cases and under 90 laboratory-confirmed cases at the date of publication, not 1,000.","imageCaption":"Health centers and treatment wards in Goma, North Kivu.","explanation":"### Context\\nPanic spread across Goma after viral messages alleged that one single health zone had surpassed 1,000 active patients, suggesting an uncontrollable surge.\\n\\n### Data Verification\\nCongo Check cross-referenced the epidemiological figures with the Provincial Health Division (DPS) of North Kivu:\\n\\n- Suspected cases in Karisimbi at the time stood at 312.\\n- Confirmed positive cases stood at 86.\\n- While health systems are under immense strain, inflating figures by more than 300% causes disproportionate public panic and hoarding of supplies.\\n\\n### Verdict\\nThe claim is **MISLEADING** because it inflates real clinical counts to trigger panic."},"sw":{"title":"Upotoshaji: Eneo la Afya la Karisimbi Halijafikisha Kesi 1,000 za Mpox","claim":"Eneo la afya la Karisimbi mjini Goma limefikisha kesi zaidi ya 1,000 zilizothibitishwa za Mpox na hospitali zimelemewa kabisa.","claimant":"Ujumbe wa hofu kwenye WhatsApp na vituo vya redio vya mitaani","verdictSummary":"UPOTOSHAJI. Ingawa Karisimbi ni moja ya maeneo yenye maambukizi mkoani Kivu Kaskazini, takwimu rasmi za idara ya afya zilionyesha kesi 312 zilizoshukiwa na kesi 86 zilizothibitishwa na maabara, na si kesi 1,000 kama ilivyodaiwa.","imageCaption":"Vituo vya afya na wadi za matibabu mjini Goma, Kivu Kaskazini.","explanation":"### Hofu Iliyotokea Goma\\nUjumbe uliosambaa mjini Goma ulisababisha taharuki ukidai kuwa eneo moja pekee limevuka wagonjwa 1,000, jambo lililosababisha watu kuogopa kwenda hospitali.\\n\\n### Takwimu Halisi za Afya\\nCongo Check ilikagua ripoti ya kila wiki ya Divisheni ya Afya ya Mkoa wa Kivu Kaskazini (DPS):\\n\\n- Idadi ya watu waliofanyiwa vipimo vya kushukiwa ilikuwa 312.\\n- Waliothibitishwa na maabara kuwa na virusi walikuwa 86.\\n- Kuzidisha idadi ya wagonjwa kwa zaidi ya mara tatu kunachochea hofu isiyo ya lazima katika jamii.\\n\\n### Uamuzi (Verdict)\\nMadai haya ni **UPOTOSHAJI** kwa sababu yanakuza idadi halisi ili kuibua taharuki."}}}],"siteSetting":{"emergencyPhone":"+243 81 000 0000","emergencyWhatsApp":"+243 82 222 2222","socialLinks":{"facebook":"https://facebook.com/congocheck","twitter":"https://x.com/congocheck","whatsapp":"https://whatsapp.com/channel/congocheck","youtube":"https://youtube.com/@congocheck"},"locales":{"en":{"siteName":"Congo Check - MpoxFacts","tagline":"Bilingual Fact-Checking Portal & Epidemic Verification Desk","emergencyBannerText":"Mpox Emergency Hotline (Toll-Free DRC): 109 / 110 | Africa CDC Support: +251 11 551 7700","aboutBrief":"Congo Check is the leading independent fact-checking organization in the Democratic Republic of the Congo and the Great Lakes region, certified by the International Fact-Checking Network (IFCN).","footerCopyright":"© 2025 Congo Check. Verified under IFCN Code of Principles. Available in English & Kiswahili."},"sw":{"siteName":"Congo Check - Ukweli Kuhusu Mpox","tagline":"Jukwaa la Ukaguzi wa Habari na Ukweli Kuhusu Magonjwa ya Mlipuko","emergencyBannerText":"Nambari ya Dharura ya Mpox (Bila Malipo DRC): 109 / 110 | Msaada wa Africa CDC: +251 11 551 7700","aboutBrief":"Congo Check ni shirika huru linaloongoza kwa ukaguzi wa taarifa nchini Jamhuri ya Kidemokrasia ya Kongo na ukanda wa Maziwa Makuu, lililoidhinishwa na Mtandao wa Kimataifa wa Wakaguzi wa Habari (IFCN).","footerCopyright":"© 2025 Congo Check. Imethibitishwa chini ya Kanuni za IFCN. Inapatikana kwa Kiingereza na Kiswahili."}}},"mpoxHubPage":{"locales":{"en":{"heroTitle":"MpoxFacts: Verified Health Information & Debunks","heroSubtitle":"Tracking, investigating, and debunking dangerous health misinformation, clinical rumors, and vaccine myths across Central and East Africa in English and Kiswahili.","alertBadgeText":"WHO & Africa CDC Health Advisory","alertHeadline":"Mpox Clade Ib Outbreak: Protect Yourself & Your Family","alertSummary":"Mpox spreads primarily through close skin-to-skin contact with infected lesions, contaminated linen, or respiratory droplets in close proximity. Free testing and supportive clinical care are provided in public health zones.","guidelines":[{"icon":"shield","title":"Avoid Direct Contact","desc":"Do not touch rash lesions, scabs, or bodily fluids of suspected or confirmed patients."},{"icon":"wash","title":"Hygiene & Cleanliness","desc":"Wash hands regularly with soap and clean water or use alcohol-based sanitizer."},{"icon":"hospital","title":"Seek Early Healthcare","desc":"Prompt clinical isolation and supportive care prevent life-threatening complications."}],"rumorReportPrompt":"Encountered a suspicious voice note, medical claim, or herbal remedy on WhatsApp or Facebook? Submit it to our verification desk."},"sw":{"heroTitle":"Ukweli Kuhusu Mpox: Taarifa Zilizothibitishwa za Afya","heroSubtitle":"Kufuatilia, kuchunguza na kutokomeza uzushi wa kiafya, taarifa za uongo na uvumi kuhusu chanjo na matibabu ya Mpox katika kanda ya Afrika ya Kati na Mashariki.","alertBadgeText":"Mwongozo wa Afya wa WHO na Africa CDC","alertHeadline":"Mlipuko wa Mpox Aina ya Clade Ib: Jilinde Wewe na Familia Yako","alertSummary":"Mpox huenezwa hasa kwa kugusana ngozi kwa ngozi na vidonda vya mgonjwa, nguo zilizotumiwa na mgonjwa, au matone ya mate kwa ukaribu mkubwa. Vipimo na matibabu yanatolewa bila malipo katika vituo vya afya vya serikali.","guidelines":[{"icon":"shield","title":"Epuka Kugusana Moja kwa Moja","desc":"Usiguse vipele, vidonda au majimaji ya mwili ya mtu anayeshukiwa kuwa na ugonjwa huo."},{"icon":"wash","title":"Usafi wa Mikono","desc":"Nawa mikono mara kwa mara kwa sabuni na maji safi tiririka au tumia vitakasa mikono."},{"icon":"hospital","title":"Nenda Hospitali Mapema","desc":"Kuanza matunzo hospitalini mapema kunazuia madhara makubwa na kuokoa maisha."}],"rumorReportPrompt":"Je, umepokea ujumbe wa sauti, tangazo la dawa ya kienyeji au madai ya kushangaza kwenye WhatsApp au mitandao ya kijamii? Tuma kwa wataalamu wetu wa ukaguzi."}}}}');

